import { GEO, onMap } from './geodata.js';

// Sydney's spatial configuration at true 1:1 scale, from the real geography in js/geodata.js (generated by
// tools/build-geodata.mjs from OpenStreetMap and City of Sydney open data).
//
// World frame: 1 unit = 1 m, x = grid east, z = grid south (north = -z), origin at Town Hall, the axes turned 8° from
// true north like the CBD's streets. The detailed play area is the CBD side and Milsons Point to North Sydney, with the
// harbour between them; everything beyond it is low-detail scenery (surroundings.js).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};

// Traffic keeps to this side of the road: -1 left, +1 right. Lane offsets count from the centre line towards it.
const DRIVE_SIDE = -1;

// ---------------------------------------------------------------------------------------------------------------------
// Land: the shore rings of each land mass (outer ring first, then lakes and docks cut into it)
// ---------------------------------------------------------------------------------------------------------------------
const SHORE_RINGS = GEO.shores.map((rings) => rings.map(toPts));
const CITY_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const rings of SHORE_RINGS) {
    for (const p of rings[0]) {
      minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    }
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();

// Every shore crossing of each 2 m row of z: an even-odd test for any point, without walking the rings
const SHORE_ROWS = (() => {
  const step = 2;
  const z0 = Math.floor(CITY_BOUNDS.minZ / step) * step;
  const n = Math.ceil((CITY_BOUNDS.maxZ - z0) / step) + 1;
  const rows = Array.from({ length: n }, () => []);
  for (const rings of SHORE_RINGS) {
    for (const ring of rings) {
      for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const a = ring[j], b = ring[i];
        if (a.z === b.z) continue;
        const lo = Math.min(a.z, b.z), hi = Math.max(a.z, b.z);
        for (let k = Math.max(0, Math.ceil((lo - z0) / step)); k < n && z0 + k * step < hi; k++) {
          const z = z0 + k * step + 1e-3;
          if (z < lo || z >= hi) continue;
          rows[k].push(a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z));
        }
      }
    }
  }
  return { z0, step, n, rows: rows.map((r) => Float32Array.from(r.sort((p, q) => p - q))) };
})();

/** Is (x, z) on the detailed land, as opposed to the harbour or the scenery beyond the play area? */
function landAt(x, z) {
  const k = Math.round((z - SHORE_ROWS.z0) / SHORE_ROWS.step);
  if (k < 0 || k >= SHORE_ROWS.n) return false;
  const row = SHORE_ROWS.rows[k];
  let inside = false;
  for (let i = 0; i < row.length && row[i] < x; i++) inside = !inside;
  return inside;
}

// ---------------------------------------------------------------------------------------------------------------------
// Roads: every driven street from the centreline graph, plus the motorways and pedestrian streets the maps name
// ---------------------------------------------------------------------------------------------------------------------
const SHORT_WORDS = [[/\bStreet\b/, 'St'], [/\bRoad\b/, 'Rd'], [/\bAvenue\b/, 'Ave'], [/\bLane\b/, 'Ln'], [/\bPlace\b/, 'Pl'], [/\bHighway\b/, 'Hwy'],
  [/\bExpressway\b/, 'Expwy'], [/\bParade\b/, 'Pde'], [/\bCrescent\b/, 'Cres'], [/\bDrive\b/, 'Dr'], [/\bTerrace\b/, 'Tce'], [/\bSquare\b/, 'Sq']];
const shortName = (name) => SHORT_WORDS.reduce((s, [re, to]) => s.replace(re, to), name);
const ROADS = [];
const RG = GEO.roadGraph;
const roadOfLink = new Map();
function roadFromLink(link) {
  const [a, b, ni, w, lanes, dir, inner, major, , kind = 0] = link;
  const pts = [{ x: RG.nodes[a * 2], z: RG.nodes[a * 2 + 1] }, ...toPts(inner), { x: RG.nodes[b * 2], z: RG.nodes[b * 2 + 1] }];
  return { name: RG.names[ni], short: shortName(RG.names[ni]), w, lanes, dir, major: !!major, highway: false, kind, pts };
}
function sceneryRoad([name, kind, flat]) {
  return { name, short: shortName(name), w: kind === 'p' ? 8 : 14, lanes: 0, dir: 0, major: kind !== 'p', highway: kind !== 'p', tunnel: kind === 't', pedestrian: kind === 'p', pts: toPts(flat) };
}

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
function placeRoad(r, sign) {
  if (sign > 0) {
    r.slot = ROADS.length;
    ROADS.push(r);
  } else {
    const last = ROADS.pop();
    if (last !== r) {
      ROADS[r.slot] = last;
      last.slot = r.slot;
    }
  }
  if (r.tunnel || !r.name) return;
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (sign > 0) {
        if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
        ROAD_GRID.get(k).push(seg);
      } else {
        const list = ROAD_GRID.get(k)?.filter((q) => q.r !== r);
        if (list?.length) ROAD_GRID.set(k, list);
        else ROAD_GRID.delete(k);
      }
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every curb island (raised footpath slab). poly: curb outline [{x, z}], holes: rings cut out of it,
// park: share covered by parkland, parkName, median: a traffic island too narrow to walk along
// ---------------------------------------------------------------------------------------------------------------------
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
function blockFromRecord([flat, holes, park, parkName, id]) {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  const narrow = area / Math.max(maxX - minX, maxZ - minZ, 1);
  return {
    id, poly, holes: holes.map(toPts), park, parkName, area, minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: narrow < 4.5 && area < 700
  };
}
// All of the tiles held, in no particular order
const BLOCKS = [];
const LAWNS = [];
const PAVEMENTS = [];
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
function placeBlock(b, sign) {
  if (sign > 0) {
    b.slot = BLOCKS.length;
    BLOCKS.push(b);
  } else {
    const last = BLOCKS.pop();
    if (last !== b) {
      BLOCKS[b.slot] = last;
      last.slot = b.slot;
    }
  }
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (sign > 0) {
        if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
        BLOCK_GRID.get(k).push(b);
      } else {
        const list = BLOCK_GRID.get(k).filter((q) => q !== b);
        if (list.length) BLOCK_GRID.set(k, list);
        else BLOCK_GRID.delete(k);
      }
    }
  }
}
// A few blocks have thousands of outline points (the Domain's has over 4,000, the median block 15). Their outline
// crossings are kept row by row, so testing a point doesn't walk the whole ring.
const ROW = 2;
function outlineRows(b) {
  const z0 = Math.floor(b.minZ / ROW) * ROW;
  const n = Math.ceil((b.maxZ - z0) / ROW) + 1;
  const rows = Array.from({ length: n }, () => []);
  const P = b.poly;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const p = P[j], q = P[i];
    if (p.z === q.z) continue;
    const lo = Math.min(p.z, q.z), hi = Math.max(p.z, q.z);
    for (let k = Math.max(0, Math.ceil((lo - z0) / ROW)); k < n && z0 + k * ROW < hi; k++) {
      const z = z0 + k * ROW;
      if (z >= lo && z < hi) rows[k].push(p.x + ((z - p.z) * (q.x - p.x)) / (q.z - p.z));
    }
  }
  return { z0, rows: rows.map((r) => Float32Array.from(r.sort((a, c) => a - c))) };
}
function insideOutline(b, x, z) {
  if (b.poly.length < 64) return pointInPoly(b.poly, x, z);
  const t = (b.table ??= outlineRows(b));
  const row = t.rows[Math.round((z - t.z0) / ROW)];
  if (!row) return false;
  let inside = false;
  for (let i = 0; i < row.length && row[i] < x; i++) inside = !inside;
  return inside;
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (insideOutline(b, x, z) && !b.holes.some((h) => pointInPoly(h, x, z))) return b;
  }
  return null;
}

// What each tile adds, kept on the tile for whatever builds from it
let mapVersion = 0;
onMap({
  addTile(tile) {
    tile.placedBlocks = tile.blocks.map(blockFromRecord);
    tile.placedLawns = tile.lawns.map((rings) => rings.map(toPts));
    tile.placedPavements = tile.pavements.map((rings) => rings.map(toPts));
    tile.placedRoads = tile.scenery.map(sceneryRoad);
    for (const b of tile.placedBlocks) placeBlock(b, 1);
    LAWNS.push(...tile.placedLawns);
    PAVEMENTS.push(...tile.placedPavements);
    for (const r of tile.placedRoads) placeRoad(r, 1);
    mapVersion++;
  },
  removeTile(tile) {
    for (const b of tile.placedBlocks) placeBlock(b, -1);
    for (const [list, gone] of [[LAWNS, new Set(tile.placedLawns)], [PAVEMENTS, new Set(tile.placedPavements)]]) {
      let n = 0;
      for (const item of list) if (!gone.has(item)) list[n++] = item;
      list.length = n;
    }
    for (const r of tile.placedRoads) placeRoad(r, -1);
    mapVersion++;
  },
  addLink(link) {
    const road = roadFromLink(link);
    roadOfLink.set(link.id, road);
    placeRoad(road, 1);
  },
  removeLink(link) {
    placeRoad(roadOfLink.get(link.id), -1);
    roadOfLink.delete(link.id);
  }
});
/** Goes up whenever the map's lists change: for anything that caches what it drew from them */
const getMapVersion = () => mapVersion;

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods, for the labels and the maps
// ---------------------------------------------------------------------------------------------------------------------
const SUBURBS = [
  ['North Sydney', -1500, 1000, -4500, -3300], ['Kirribilli', 150, 1000, -3300, -2350], ['Milsons Point', -420, 150, -3300, -2350], ['Lavender Bay', -1500, -420, -3300, -2350],
  ['The Rocks', -560, 100, -2350, -1250], ['Circular Quay', 100, 420, -2350, -1250], ['Royal Botanic Garden', 420, 1120, -2350, -700], ['Barangaroo', -1100, -560, -2350, -600],
  ['Woolloomooloo', 1120, 1500, -1400, -240], ['Potts Point', 1500, 2700, -2350, 0], ['Darling Harbour', -760, -220, -600, 780], ['Pyrmont', -2100, -760, -2350, 780],
  ['Ultimo', -2100, -300, 780, 2100], ['Haymarket', -300, 200, 420, 1080], ['Chippendale', -300, 400, 1080, 2100], ['Surry Hills', 400, 1450, 760, 2100],
  ['Darlinghurst', 1120, 2000, -240, 760], ['Paddington', 2000, 2700, 0, 2100], ['Sydney CBD', -220, 1120, -1250, 420]
];
function suburbAt(x, z) {
  for (const [name, x0, x1, z0, z1] of SUBURBS) if (x >= x0 && x < x1 && z >= z0 && z < z1) return name;
  return 'Sydney';
}

// ---------------------------------------------------------------------------------------------------------------------
// Places. Landmarks are modelled by landmarks.js at their real sites; heading 0 faces south (+z), PI north
// ---------------------------------------------------------------------------------------------------------------------
const SPAWN = { x: 397, z: -1000, heading: Math.PI }; // Macquarie St, heading for the Opera House
const LANDMARK_SITES = {
  operaHouse: { x: 505, z: -1862 },
  sydneyTower: { x: 143, z: -311 },
  townHall: { x: 2, z: 26 },
  centralStation: { x: 92, z: 1118 },
  lunaPark: { x: -119, z: -2839 }
};
const TELEPORT_LOCATIONS = {
  macquarie: { ...SPAWN },
  circularQuay: { x: 240, z: -1316, heading: Math.PI * 0.5 },
  townHall: { x: 9, z: -42, heading: 0 },
  hydePark: { x: 283, z: -39, heading: 0 },
  darlingHarbour: { x: -272, z: 489, heading: Math.PI },
  centralStation: { x: 174, z: 1001, heading: 1.148 },
  kingsCross: { x: 1451, z: -8, heading: 2.5 },
  northSydney: { x: -541, z: -3570, heading: Math.PI },
  harbourBridge: { x: -312, z: -1422, heading: 2.87 } // on the deck's south end, heading north
};
const LANDMARKS = [
  { id: 'opera', name: 'Sydney Opera House', short: 'Opera House', x: 505, z: -1862, district: 'Bennelong Point' },
  { id: 'bridge', name: 'Sydney Harbour Bridge', short: 'Harbour Bridge', x: 12, z: -2350, district: 'Sydney Harbour' },
  { id: 'tower', name: 'Sydney Tower', short: 'Sydney Tower', x: 143, z: -311, district: 'Sydney CBD' },
  { id: 'townhall', name: 'Sydney Town Hall', short: 'Town Hall', x: -65, z: 21, district: 'Sydney CBD' },
  { id: 'central', name: 'Central Station', short: 'Central', x: 92, z: 1118, district: 'Haymarket' },
  { id: 'luna', name: 'Luna Park', short: 'Luna Park', x: -119, z: -2839, district: 'Milsons Point' }
];

/** Street corner, landmark or harbour name at any world (x, z) */
function getLocationLabel(x, z) {
  for (const lm of LANDMARKS) if (Math.hypot(x - lm.x, z - lm.z) < 90) return lm.name;
  const block = blockAt(x, z);
  if (block && block.park > 0.6 && block.parkName) return block.parkName;
  const near = nearestRoads(x, z, 150);
  if (near.length >= 2) return `${near[0].road.short} & ${near[1].road.short}`;
  if (near.length) return near[0].road.short;
  return landAt(x, z) ? suburbAt(x, z) : 'Sydney Harbour';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds: the main
// road is green until mainAmber, amber until mainRed; the side road is green from mainRed until sideAmber, amber until
// the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off only on the WALK,
// the first `walk` seconds of its green: long enough before the cross traffic's green for the slowest walker to get
// across the widest road.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for main road (or side road) traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside main road (or side road) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

export {
  BLOCKS,
  CITY_BOUNDS,
  DRIVE_SIDE,
  LANDMARKS,
  LANDMARK_SITES,
  blockFromRecord,
  getMapVersion,
  sceneryRoad,
  LAWNS,
  PAVEMENTS,
  ROADS,
  SHORE_RINGS,
  SIGNAL_TIMING,
  SPAWN,
  SUBURBS,
  TELEPORT_LOCATIONS,
  blockAt,
  getLocationLabel,
  isTypingInField,
  landAt,
  nearestRoads,
  shortName,
  signalPhase,
  suburbAt,
  walkSignal
};
